INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b1bf90f0-9a95-4979-bcab-c88c65ddc34a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$51. óra: A kör$q$, $q$A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "93b0ca29-f959-4b18-a734-64cd6e8d72a4", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "8dbd7b73-bcb3-43bd-8241-aef246039f46", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "5a2ebc7d-715b-4999-ad70-ec32da9a60cf", "text": "d = r / 2", "isCorrect": false}, {"id": "5fec3faa-8bbc-4df9-a75f-992662bcfe90", "text": "d = r + 5", "isCorrect": false}, {"id": "23ba1691-0a32-428c-b661-590c3d1ff5f5", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "982fa5d0-1c60-4064-9393-985ef0cf2040", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "ee8aa2b5-ea43-4722-b209-fe93cfb655a0", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "05d7f575-27fa-406e-a819-ce74de4ae442", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "d8e4cb0a-c7f1-4f1f-8c74-3b7765f89097", "text": "Igaz", "isCorrect": true}, {"id": "27ca294b-b2b9-425e-a7b1-7828979de664", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6a31c843-bfdb-44ed-8c4e-4012a2fde582", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "f5713739-1a51-4de3-8b60-fa9c1e8043f4", "text": "Az átmérő", "isCorrect": true}, {"id": "d90808be-ec52-4dcc-8394-f76216657716", "text": "A sugár", "isCorrect": false}, {"id": "60b9fdaa-02ad-4ae3-8fc7-7d8f09863f9d", "text": "A körív", "isCorrect": false}, {"id": "1c69fb51-8869-4de0-8c57-91f6b2ac94db", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "18695923-726c-4c57-bd45-ed00ee7fbe4c", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "56e3bc8b-3440-4587-a68e-9c7f32a8f9d1", "text": "Igaz", "isCorrect": true}, {"id": "7cee530e-e7bb-4853-b426-bf123da63363", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d25ea97e-7429-4d4b-ab51-c76dd1e7446a", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "a8ea329a-a571-4a68-844a-f53b3c4b0c07", "text": "Igaz", "isCorrect": true}, {"id": "694db496-68da-49a0-8ccd-b9143b9c3cad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3cdae9f3-ce57-4954-b7db-f654cdf111ca', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$52. óra: A szakasz felezőmerőlegese$q$, $q$A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "d3dce426-0200-4e00-aca7-11c644fe83b2", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "6b4699da-4e20-49f3-9b7a-ea5ae5a86620", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "82282cc0-a293-452a-89b3-71773417d4c2", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "d4eba948-15bd-4c3f-bc5e-1fef732fe96c", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "792adaab-9ba9-436d-ab27-74ec43a1ef9d", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "a582e663-b37e-4777-8e6a-09e568dfaee5", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "e9853945-870c-4f73-bc3f-d30ee0d8aba2", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "96f339fe-7887-4625-84db-349bb6f423ad", "text": "Igaz", "isCorrect": true}, {"id": "bf975eb7-043e-4d95-85d1-ee3efa898a18", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "58ac5378-1e3b-49b4-b2d0-f45ad2006443", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "6176d451-ec11-4091-ae23-d68b1a7ebb7d", "text": "Igaz", "isCorrect": true}, {"id": "8dfc3c2a-32d1-47a6-9409-862c212a9e4c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2fe97802-38ac-43cb-a38c-4ce1cf5ee75c", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "26b6ae03-a26e-4ff1-88af-70e54aa79e1b", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "f123147a-f4f9-4889-9eea-e9bf297f92e3", "text": "Igaz", "isCorrect": true}, {"id": "55959459-5932-4aa7-ac48-6cdc6fc48083", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "85feaf69-8602-48d8-81d0-59c5a1491cd7", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "049c8ee0-d6c8-4ade-907a-057f4b20cc83", "text": "Igaz", "isCorrect": true}, {"id": "93f6d2c3-55f0-4c99-963f-a213c3b578de", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('95de4829-9b83-4105-a605-b858e1bea12e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$53. óra: Szerkesztések$q$, $q$Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "453b08b6-69e8-43f7-97f0-e31be025f387", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "69af424d-48ff-4202-8dbf-d1b28465188e", "text": "Körzőt", "isCorrect": true}, {"id": "e2a20578-1b09-4819-b968-5242bfbefe02", "text": "Szögmérőt", "isCorrect": false}, {"id": "71d44829-3595-4cf8-b315-0ab0beae2c7b", "text": "Radírt", "isCorrect": false}, {"id": "ad6fc289-33b3-47c2-95bf-54a773f92279", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "af856189-da08-4093-b2be-1dd320059be3", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "49c7aa2e-b73c-422a-946b-d6caae42813f", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "b4be9887-b97d-4283-af4f-80ffbfd7f81d", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "4dc995df-d417-4f5d-a0c8-641f911b1bdc", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "43d9c714-a100-48bb-87e4-531587c1ab4b", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "2a341d93-59bb-47fa-84af-3e8abc4d5506", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "e7ab08fc-6fe4-400a-b223-b91247ade7e4", "text": "Igaz", "isCorrect": true}, {"id": "9fa65fab-7d08-4097-8be4-037e532bf1f1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b5c00614-d3c5-468d-883d-e4bcee45fa5f", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "2fb31373-49c2-4d1c-8c3b-027422292f20", "text": "Igaz", "isCorrect": true}, {"id": "71f0db14-55b0-4bc4-b0ca-43b757eeb467", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "90b2b89b-64e8-4bc8-9d96-4b378e4449e7", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "4ef9e343-657a-44dc-9806-bda2f7f30f7e", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "1793483d-8724-49d2-9a23-2c53dfbddcf1", "text": "Igaz", "isCorrect": true}, {"id": "4e83381c-6d04-48f3-9b05-3e83e0e7e836", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "88dc8de6-db74-45cc-bde4-0b8e642a08ea", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "02e36a13-7367-4fc7-8454-a443bf1e9fc9", "text": "Igaz", "isCorrect": true}, {"id": "bd4768bd-82c2-44d8-b769-880c2b052a36", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4906565d-a28c-41c3-b54d-04a1dca1c384', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$54. óra: Szerkesztések II.$q$, $q$Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "b56c6f29-e670-4b07-be7e-634557cd7b00", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "c8b04738-8d59-474f-8fbe-8cfc15a32b4e", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "3f2bc063-f962-4c70-ab38-55038c0deb8b", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "9ad23b41-3f43-4b62-90b5-db8f3bdec0dd", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "5c770aa4-5466-4dcf-9925-aa08ffb04413", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "94fd0250-ca8c-4c8d-9969-7e546cfa5c09", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "32b509d8-6255-430e-a391-0ded2e17c8eb", "text": "Igaz", "isCorrect": false}, {"id": "c18810ac-6736-41ec-9323-2048f7a52500", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "6f263021-2ebb-457c-ad36-a6d8437a96c5", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "ad848c47-c009-445c-af4b-87ace2cc4039", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "cd3ba5ea-ea69-416f-b250-95f805df916e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6734e946-689c-4598-94ce-2f6b1315e3cf", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "a7c2b175-fbb3-426d-8f2b-b1446a616e0f", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "55d6a30b-eb62-4158-a3aa-c066758c1eb2", "text": "Igaz", "isCorrect": true}, {"id": "3499eb88-099d-4b1b-b4b3-f32606cae217", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f4b12be-ff9c-4e42-9fb4-c7e1f30af324", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "ea4d62e3-e587-4407-aa97-b3f32aedd1e6", "text": "Igaz", "isCorrect": false}, {"id": "ebf40029-b262-41a4-86a8-6646328f0bce", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "7862c5ea-8385-4105-8759-70814e7a7972", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "c2ef5ea4-e4a8-4ea3-b6a0-a94cd8fac74f", "text": "Igaz", "isCorrect": true}, {"id": "b43cc894-c7bb-4957-b012-b34e49b2d49e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b7919d15-cb74-4647-a231-68301ef75376', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$55. óra: Számonkérés$q$, $q$Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "edb20d90-780b-42db-8a76-7bd7e832f459", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "66a8544d-1152-47e0-a9e6-72d1baa54f74", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "23824e50-c0c3-4c53-b913-baf4220ccfd2", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "f65fefaa-3257-48e5-a54b-6ce04fbc58ce", "text": "Igaz", "isCorrect": false}, {"id": "999d40e5-415e-4ed9-ba6d-6a217c512384", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "4a6d2c5a-fe32-4fe2-9861-69260d7717c2", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "52714b43-d738-4750-9e3a-392f1c6d2594", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "4996cdd0-dbd1-4fd5-b81e-b01ac14bc20d", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "fe94efee-c207-48ab-8c5c-20bfe1eebd0c", "text": "Igaz", "isCorrect": true}, {"id": "340b8ed7-6342-42ad-b073-5a27cedf9980", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bbad26a2-0600-451c-bcdc-b0e45600462f", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "0bc21173-0084-4b91-bd77-8697632f5362", "text": "Tompaszög", "isCorrect": true}, {"id": "01c23d77-c7a0-4a9a-b886-7065840df987", "text": "Hegyesszög", "isCorrect": false}, {"id": "9f2c770f-60ca-4bbc-8b95-e1fe6238dbb1", "text": "Derékszög", "isCorrect": false}, {"id": "0a21ecae-a113-4c99-b22d-4b9fcd717d78", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "a8f0c720-465d-4601-a696-5c4b5328b2dc", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "8e64c4bd-74db-46ec-9cb2-de458d63d466", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "55822204-ce47-4ceb-9873-700f3dbc4c57", "text": "Igaz", "isCorrect": true}, {"id": "581018ae-225d-4762-9fec-eb935ff473bb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "89baeeb7-31d6-4a6e-8cf9-8026b403f1db", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e5440ba4-ae78-4f5c-9ce9-99b71856fdd8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$56. óra: Matematikai játékok$q$, $q$Geometriai kirakók (Tangram), alakzatok építése, stratégiák.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "5c06c69e-14cf-4670-9589-cf5947e8e3a7", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "1cda45e0-a224-470d-9fa3-b5dc671ea030", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "6d33e838-32cf-41f4-8d95-0d9e4ca363c2", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "2eab4f1a-40ba-4e1c-9643-38f07a34b654", "text": "7 négyzet", "isCorrect": false}, {"id": "b58b7018-5a54-4fea-a2cf-984a7093f9e3", "text": "7 kör", "isCorrect": false}, {"id": "eabab3f9-761f-4b36-9e74-1f49422b4d5a", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "b4c0825c-40bf-4471-afcf-bf82597b951d", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "daf7caeb-1ac3-4573-9019-9013981f2f8e", "text": "Igaz", "isCorrect": true}, {"id": "dc6e897e-38ff-4313-9fda-e5fdcbf29c7f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "615c6261-084d-4e66-b096-288703f11841", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "80945cad-8b41-4642-b6e1-9cfe760aa49f", "text": "Igaz", "isCorrect": true}, {"id": "0dd3362f-c8ac-4fee-a07a-e4073d9a1971", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3515f0b1-1214-4dcc-893b-bd90bb58170f", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "1490104a-12c4-46ae-8ad9-c1c9f0fc2944", "text": "Igaz", "isCorrect": true}, {"id": "340e0e7f-b65b-4b0f-bb32-b5b944ff8029", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b19edc3b-ff7c-448e-a771-0bb87be50fec", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4185d45d-335f-4351-85ad-4214437b0442", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "d7022a89-899e-4eed-b610-132591131f4e", "text": "Igaz", "isCorrect": true}, {"id": "433563dd-c2ee-4ca7-a1a4-d7519e47727e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('921a6c22-793a-44da-a585-e85496ab18cc', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$57. óra: Tengelyes tükrözés$q$, $q$Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A').$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "69caee3b-253f-4576-b140-841a3f3873ce", "text": "Mi a tengelyes tükrözés lényege egy 't' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "ff5e3841-fa47-4617-8179-9d6c808da761", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "2850f9b3-6a6b-4109-bf3b-770361e72775", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "e2b09b34-c190-4176-8cc0-52b72c4e1cf2", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "d104589d-12f9-435a-8bd3-2355848ea15a", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "44778973-e3a4-4af5-a91c-4ae71bb3dc1c", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "3d7db5eb-527e-4fad-ae2d-a070650f692d", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "cf579002-8a1b-4f2d-a458-669bfa1892b4", "text": "Az origóban", "isCorrect": false}, {"id": "f1dcaef7-a5ed-448d-b584-923e6d7cd3bd", "text": "Végtelenben", "isCorrect": false}, {"id": "9d60bc47-dbbc-44f9-9625-c29916b7e716", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "6b27a82c-c3d8-4586-a228-e66dc0f47b79", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "3eb01d86-9e72-4063-8f42-215050e18cbd", "text": "Milyen messze van a P pont a P' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "3b9ffd46-7cbb-4ac4-b339-9ba85c5c3ebd", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "f3c3d528-7fca-4d7d-88f5-392fa53547c8", "text": "Igaz", "isCorrect": true}, {"id": "d574a643-cbbc-4941-902c-a2d17c57589d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aa6042e3-5e2f-4a41-928a-c2d5c4a4f479", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "c0f0d6af-ff59-4e1f-b540-aebd5b9eead1", "text": "Igaz", "isCorrect": true}, {"id": "fc1cc04a-d700-4a05-8449-905fb532b378", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "385072bf-d3f1-4527-b5d6-f706a721e5a8", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "558886e4-76df-4907-8486-dc3a69aaaada", "text": "Igaz", "isCorrect": true}, {"id": "9af81a49-21e4-42a4-8091-e7002afadc1e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7cd7aeb6-6f23-455d-98d7-863dbce4569b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$58. óra: A tengelyes tükrözés tulajdonságai$q$, $q$Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "b9972472-93e8-44fb-ad6b-0fc4882caa1a", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "771793d7-0d0f-4f7a-bd1c-8b6d74041a3e", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "99aac1ef-4b71-483c-89f6-689b14dd9f75", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "cc9baaef-5026-4b16-ab65-7e5be74e6d10", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "4e13cf0c-ec46-4773-8d78-565096a84deb", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "efbfe8c5-ad20-4be2-9d6b-2e8fba03eb43", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "d9b6c446-65f3-4e5d-a1df-d33219d6ffad", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "cfcc0c65-fe2e-4cf1-953c-dd0fd38bc537", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e02d3a80-3e6a-4db1-b2f4-cdbe153c09fd", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "39ae0e93-efab-46e5-a992-7bad12fe7246", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "ad40d7bc-abb1-4559-b812-c95c283c8684", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4554d5ee-c617-49f1-842f-ab1d9346b213", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "51864629-da4a-4314-ae20-c5d32314caf4", "text": "Igaz", "isCorrect": true}, {"id": "3cc418c2-7e58-4a09-bdaf-72a979e45fe3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3dc69ce2-f35d-45dd-a406-3a70d642f621", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "c9c6a58e-3e58-46b0-95af-1662fb700b72", "text": "Igaz", "isCorrect": true}, {"id": "2b10587a-9810-4c98-a576-cbc78e785b60", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "580f9e94-37cc-47bc-bf21-3d965e63b08a", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "7973dc52-c3c3-439d-a937-8f5eb09bb3d6", "text": "Igaz", "isCorrect": true}, {"id": "13581e37-b2ea-4b26-87c7-a052a9246d10", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc6c20ae-9b59-4150-a695-cb7803976c04", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "42a1ce48-e3e9-497f-8651-b148a64f03d8", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "ff521134-cc49-4154-a9fd-dfd67b72efe4", "text": "Csak 1", "isCorrect": false}, {"id": "c6a63cf1-6309-4e5a-a31a-de45c106555f", "text": "Nincs egy sem", "isCorrect": false}, {"id": "d162cfa3-4e38-4398-bd2a-b7f83bcd94d8", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b444974b-435d-4a85-8a86-67657a781473', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$59. óra: Gyakorlóóra$q$, $q$Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "85e54947-c730-4cf0-9c2d-837f6dfba855", "text": "Hogyan szerkesztjük meg egy P pont 't' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "ca330fb1-25c2-4201-ab78-0592f6c509b3", "text": "Merőlegest állítunk P-ből 't'-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "7d7dc400-aa47-45e8-9e16-19cdba0c374f", "text": "Párhuzamost húzunk 't'-vel", "isCorrect": false}, {"id": "ebaf5a6e-2fca-4fe6-bdad-36f26e182b07", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "75dfbed5-44a7-4eb9-adc3-9db0c1fdf167", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "6032ed79-2b5f-4969-a525-186f02a90f4f", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "48554903-1c49-406a-ba4b-95a026e92f33", "text": "Igaz", "isCorrect": true}, {"id": "46ddcc2b-7a32-4754-a60a-f24eebae82a6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "09a86ef5-9291-4943-8a7b-d926c9558597", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "e9ef6e52-0ffe-4a08-958d-0afa9f85673e", "text": "Önmagában (P = P')", "isCorrect": true}, {"id": "b0c3e688-9851-42d4-a98e-06676e0fd211", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "0aa1c0f9-e0c7-4428-9941-8c7f66a6278c", "text": "A sík szélén", "isCorrect": false}, {"id": "f3149fbc-7a88-4c7a-9189-49e4ab98ab4f", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "6051ac70-a7d6-49f0-b1bf-6e94c4ad5f29", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "8a192f48-ea6d-4a79-8add-8eb0411a82ba", "text": "Igaz", "isCorrect": true}, {"id": "8691b41c-144a-4f82-ae88-52cdc8f34563", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d7df909d-8eb5-4077-9f53-2bf191e8a9c8", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "16b152aa-7f87-46ac-adda-997211735f52", "text": "A", "isCorrect": true}, {"id": "d2312c56-b71a-49f9-bde6-071fd092be6e", "text": "F", "isCorrect": false}, {"id": "2ab91a7c-11d5-41d3-9238-e4f044857ccc", "text": "L", "isCorrect": false}, {"id": "1256457a-91ad-4506-b711-262dd2e749f7", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "23b3229e-a662-437b-8475-a15d92ac6a16", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "ce3845ec-dd69-4670-b1b1-727d52c6c133", "text": "E", "isCorrect": true}, {"id": "b53d916f-2e6e-47e4-a93c-31dc78da0bc0", "text": "F", "isCorrect": false}, {"id": "235a76ff-7bee-49fa-b032-eb1753f62449", "text": "G", "isCorrect": false}, {"id": "e3a914e3-87b8-4dbc-ac98-58ac6890cfa4", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "351782a9-896e-4707-8150-98b87c05ad6c", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "414f6d79-0d49-4448-bb76-00ecdee4ce4d", "text": "Igaz", "isCorrect": true}, {"id": "0bca662b-d828-429e-b949-18e70dba6c49", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('009a7e62-96e6-47a2-9ecd-a75850550147', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$60. óra: Tengelyes szimmetria$q$, $q$Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Geometria, tengelyes tükrözés$q$, $q$[{"id": "b3edb300-1fa1-4f60-83d1-8850e099e090", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "04ea1d13-54c0-4f19-a59d-78debf6e4f31", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "d02ee373-ca1b-4062-a3ae-c4f5dff1b750", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "4325afb8-6e52-4e29-a46d-2ffb6a5473bd", "text": "Ha kerek", "isCorrect": false}, {"id": "39849d68-04f2-4888-a815-1e2f5a8bf1c8", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "0740ec4e-8872-48b8-bf7b-75e3bdbd2697", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "8a2b1ec4-2002-4ebe-ad24-3b4ddec5aa22", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "f831438c-a25b-4154-8afe-3f0b11064e71", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "1565e2fd-1659-498b-838d-b9a87911f9f9", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "b028d754-5285-442e-aed7-e38b53ad6621", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "9e211075-6f02-42ed-872e-ef74ca9615fb", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "b68693c0-5b5a-478d-8285-4fc0d1269445", "text": "Igaz", "isCorrect": true}, {"id": "7fff77c3-ceea-4fbf-bb19-0564d923c5a7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f610aa52-c134-4aa7-abdf-c056db267c2d", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "22dea23b-21bd-47bb-9939-f36221e55c27", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "396380cc-808e-4f05-8e25-c238cd251c7a", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "cdd20156-4c35-49c2-9f54-a4c5b507452e", "text": "1", "isCorrect": false}, {"id": "61bb2ab1-7eee-4194-b784-4cc9a7e6a2e2", "text": "2", "isCorrect": false}, {"id": "6c53b507-919f-4bca-88a5-8f5e6eb477d8", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "3b9ed805-b049-4ce8-b9d9-09c7e94e04cd", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "a7a22cb8-97b5-4d03-978f-c2ec200dbf58", "text": "Igaz", "isCorrect": true}, {"id": "74d98b00-8130-46b9-8daa-b082e8ecb672", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d290e631-8d42-4761-a865-68ec580d562c", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;